    "Не передавайте пароли и коды из сообщений. Уточните запрос через официальный канал организации.": "Хаттардың парольдері мен кодтарын бермей, хабарды ұйымның ресми арнасы арқылы анықтаңыз.",
    "Не принимайте решение только по результату автоматического поиска.": "Автоматты іздеу нәтижесімен ғана шешім қабылдамаңыз.",
