    "Это ваш личный семейный план. Совместный доступ с других устройств пока не подключён. Подготовка сводки не открывает доступ к данным.": "Бұл сіздің жеке отбасылық жоспарыңыз. Басқа құрылғылардан ортақ қолжетімділік әлі қосылмаған. Кіріспе жасау деректерге қолжетімділікке мүмкіндік бермейді.",
    "Это ваш план, а не подтверждение правового статуса.": "Бұл сіздің жоспарыңыз, заңдық мәртебесін растау емес.",
