    "Это ваши личные черновики. Они сохраняются в аккаунте, но не отправляются сотрудникам автоматически.": "Бұл сіздің жеке сызбаларыңыз. Олар тіркелгіңізде сақталады, бірақ қызметкерлерге автоматты түрде жіберілмейді.",
    "Это действие изменит только записи на этом устройстве.": "Бұл әрекет тек осы құрылғыдағы жазбаларды ғана өзгертеді.",
