    "Это обзор ваших черновиков, а не кабинет сотрудника фонда. Изменения видны только в этом браузере.": "Бұл сіздің жобаларыңыздың шолуы, Фонд қызметкерінің кабинеті емес. Өзгерістер тек осы браузерде ғана көрінеді.",
    "Это ориентир по вашим записям, а не подтверждение задолженности.": "Бұл сіздің жазбаларыңыздың анықтамасы, қарызды растау емес.",
    "Это подключение уже закрыто.": "Бұл қосылым қазірден бастап жабылып жатыр.",
