    "Записи плана, семьи, работы и личные черновики сохраняются в вашем аккаунте на сервере. Гостевые записи не переносятся автоматически.": "Запісы плана, сям'і, працы і асабістых праектаў захоўваюцца ў вашым рахунку на серверы. Запісы гасцей не перавозяцца аўтаматычна.",
    "Записи превышают лимит серверного хранилища. Скачайте резервную копию.": "Запісы перавышаюць абмежаванне сервера.",
    "Записи сохраняются на сервере в вашем аккаунте. Гостевые записи не перенесены. Файлы остаются на этом устройстве; на другом устройстве их потребуется прикрепить заново.": "Запісы захоўваюцца на серверы ў вашым рахунку. Запісы гасцей не пераносяцца. Файлы застаюцца на гэтым прыладзе; на іншым прыладзе іх трэба будзе зноў прымацаваць.",
    "Записи удалены.": "Запісы выдаленыя.",
    "Записывайте согласованные суммы. Расчёт в приложении не подтверждает размер юридически установленного долга.": "Запішыце ўзгодненыя сумы. Разлік у дадатку не пацвярджае памер юрыдычна вызначанага доўгу.",
    "Запись больше не существует.": "Запісу больш няма.",
    "Запись началась. Максимум 3 минуты.": "Напіс пачаўся. Максімум тры хвіліны.",
    "Запись не найдена.": "Запіс не знайшлі.",
    "Запись недоступна в этом браузере. Используйте готовый аудиофайл или текст.": "Запіс не даступны ў гэтым браўзэры. Выкарыстоўвайце гатовы аўдыёфайл або тэкст.",
    "Запись оказалась пустой. Попробуйте ещё раз.": "Запіс пусты. Паспрабуйце яшчэ раз.",
    "Запись сохранена на устройстве.": "Запіс захоўваецца на прыладзе.",
    "Запись хранится на устройстве.": "Запіс захоўваецца на прыладзе.",
    "Запишите понятное объяснение или вопрос. Не оставляйте непонятные пункты без внимания.": "Запішыце зразумелае тлумачэнне або пытанне. Не пакідайце незразумелыя пункты без увагі.",
    "Запишите рассказ и добавьте короткое пояснение для специалиста.": "Запішыце гісторыю і дадайце кароткае тлумачэнне для спецыяліста.",
    "Запишите то, что умеете: профессию, работу с инструментом, пройденный курс или опыт общения с клиентами.": "Запішыце, што вы ведаеце: прафесію, працу з інструментам, праходжанне курса ці досвед зносін з кліентамі.",
    "Запишите условия, которые нужно обсудить до подписания документов.": "Запішыце ўмовы, якія трэба абмеркаваць да падпісання дакументаў.",
