    "Здесь можно составить план, вести смены и выплаты, подготовить обращение, собрать семейные дела и сохранить материалы.": "Тут можна скласці план, правесці змену і выплаты, падрыхтаваць зварот, сабраць сямейныя справы і захоўваць матэрыялы.",
    "Здесь появятся ваши записи о звонках, встречах и следующих шагах.": "Тут будуць змешчаны вашыя запісы званкаў, сустрэч і наступных крокаў.",
    "Здесь — внешние официальные сервисы и организации, не подключённые партнёры «Моста». Язык приёма, стоимость, часы и возможность записи нужно уточнить у них. Ссылки сверены 15.11.2026.": "Тут знешнія афіцыйныя сэрвісы і арганізацыі, не падключаныя партнёры Моста.",
