    "Кому, за что и на основании какого документа предлагают заплатить?": "Каму, за што і на якой дакуменце прапануюць плаціць?",
    "Конкретные требования зависят от гражданства, цели поездки и региона. Уточняйте их у специалиста и в официальных источниках. Сеть передачи дел между организациями в этой версии не подключена.": "Канкрэтныя патрабаванні залежыць ад грамадзянства, мэты падарожжа і рэгіёну. Увядзіце іх у спецыяліста і ў афіцыйных крыніцах.",
