    "Личная задача из маршрута. Дата выбрана для планирования, не является юридическим сроком.": "Персанальная задача з маршруту. Дата выбрана для планавання, не з'яўляецца юрыдычным тэрмінам.",
    "Личная запись не назначает сотрудника и не отправляет уведомление.": "Асабістая запіс не прызначае супрацоўніка і не адпраўляе паведамленне.",
