    "Личные черновики не отправляются автоматически. Создавайте и отслеживайте отправленные обращения в отдельном кабинете.": "Асабістыя праекты не адпраўляюцца аўтаматычна.",
    "Личные черновики сохраняются в аккаунте. Вложения остаются на этом устройстве. Для обращения к сотруднику откройте": "Персанальныя малюнкі захоўваюцца ў рахунку. Уклады застаюцца на гэтым прыладзе.",
