    "Скачайте календарь и импортируйте его в приложение календаря. В события добавлено напоминание за день; фактическое уведомление зависит от настроек вашего календаря.": "Дадаць наўзагрузку календара і імпартаваць яго ў дадатак календара. У падзеі дадаецца напамін за дзень; фактычнае паведамленне залежыць ад налад календара.",
