    "Без дат учитываются все записи. Выплаты отбираются по дате получения: уточните, за какой период они были.": "बिना तारीख के, सभी रिकॉर्ड को ध्यान में रखा जाता है। भुगतान प्राप्त करने की तारीख के अनुसार लिया जाता हैः यह निर्दिष्ट करें कि वे किस अवधि के लिए थे।",
    "Без даты": "तारीख नहीं",
