    "Биёед нишондодҳои ҳисобкунакҳоро нависем.": "हम एक साथ गणना के आंकड़े लटका देंगे।",
    "Будет скачан текстовый файл. Вложения нужно скачать отдельно. Проверьте содержимое перед самостоятельной передачей.": "एक पाठ फ़ाइल डाउनलोड की जाएगी. आपको अलग से डाउनलोड करने की आवश्यकता है. इसे स्वतंत्र रूप से प्रसारित करने से पहले सामग्री की जांच करें.",
    "Будут очищены личные записи V2 на сервере и локальные вложения этого аккаунта. Отправленные в кабинет обращения не удаляются.": "सर्वर पर V2 व्यक्तिगत रिकॉर्ड और इस खाते के स्थानीय ऐड-ऑन को साफ किया जाएगा।",
    "Будут очищены личные записи на сервере и локальные вложения этого аккаунта. Отправленные в кабинет обращения не удаляются.": "सर्वर पर व्यक्तिगत रिकॉर्ड और इस खाते के स्थानीय ऐड-ऑन को साफ किया जाएगा।",
    "Будут удалены гостевые записи и вложения только второй версии.": "केवल दूसरे संस्करण के लिए अतिथि रिकॉर्ड और ऐड-ऑन हटाए जाएंगे।",
    "Будут удалены запись и её файлы с этого устройства.": "इस डिवाइस से रिकॉर्ड और उसकी फाइलें हटा दी जाएंगी।",
    "Будут удалены текст, записи и приложенные к этому черновику материалы из этого устройства.": "इस डिवाइस से पाठ, रिकॉर्ड और उस स्केच से जुड़े सामग्री हटा दी जाएगी।",
    "Бул суроо боюнча кайда кайрылсам болорун айтып коюңузчу.": "यह सवाल है कि मैं आपको बताऊंगा कि मैं कहां जा सकता हूं।",
    "Бул тапшырманы дагы бир жолу түшүндүрүп бериңизчи.": "ये सब एक बार और समझाओ।",
