    "Добавьте человека, с которым можно связаться, и полезный адрес. Проверьте, открывается ли скачанная карточка на вашем телефоне.": "एक संपर्क व्यक्ति और एक उपयोगी पता जोड़ें, और अपने फोन पर डाउनलोड कार्ड खोलने की जाँच करें।",
