    "Записать показания счётчиков и переданные ключи": "गणनाओं और दिए गए कुंजी के संकेतों को दर्ज करें",
    "Записаться на встречу, найти занятия русским языком, обсудить документы с куратором. Задачи здесь организационные: индивидуальные требования уточняйте у специалиста.": "बैठक में नामांकन करें, रूसी भाषा के लिए कक्षाएं खोजें, संचालक के साथ दस्तावेजों पर चर्चा करें।",
    "Записи восстановлены. Вложения хранятся отдельно.": "रिकॉर्ड बहाल हो गए हैं, इनपुट अलग से रखे गए हैं।",
    "Записи изменились в другой вкладке или на другом устройстве. Сохраните свою копию и загрузите актуальные записи.": "किसी अन्य टैब या डिवाइस पर रिकॉर्ड बदल गए हैं. अपनी प्रति सहेजें और अद्यतित रिकॉर्ड लोड करें.",
    "Записи на этом устройстве": "इस डिवाइस पर रिकॉर्ड",
    "Записи плана, семьи, работы и личные черновики сохраняются в вашем аккаунте на сервере. Гостевые записи не переносятся автоматически.": "आपके प्लान, परिवार, काम और व्यक्तिगत रूप से आपके खाते में सर्वर पर रिकॉर्ड रखे जाते हैं।",
    "Записи превышают лимит серверного хранилища. Скачайте резервную копию.": "रिकॉर्ड सर्वर की सीमा से अधिक हैं। बैकअप डाउनलोड करें।",
    "Записи сохраняются на сервере в вашем аккаунте. Гостевые записи не перенесены. Файлы остаются на этом устройстве; на другом устройстве их потребуется прикрепить заново.": "रिकॉर्ड आपके खाते के सर्वर पर संग्रहीत हैं. अतिथि रिकॉर्ड नहीं हैं. फ़ाइलें इस डिवाइस पर रहती हैं; किसी अन्य डिवाइस पर उन्हें फिर से संलग्न करना होगा.",
    "Записи удалены.": "रिकॉर्ड हटा दिए गए हैं।",
    "Записывайте согласованные суммы. Расчёт в приложении не подтверждает размер юридически установленного долга.": "अनुबंध में दिए गए राशि को लिखें। अनुबंध में दिए गए विवरण कानूनी रूप से निर्धारित ऋण की मात्रा की पुष्टि नहीं करते हैं।",
    "Запись больше не существует.": "रिकॉर्ड अब नहीं है।",
    "Запись началась. Максимум 3 минуты.": "रिकॉर्डिंग शुरू हुई, अधिकतम 3 मिनट।",
    "Запись не найдена.": "रिकॉर्ड नहीं मिला।",
    "Запись недоступна в этом браузере. Используйте готовый аудиофайл или текст.": "इस ब्राउज़र में रिकॉर्डिंग उपलब्ध नहीं है. एक तैयार ऑडियो फ़ाइल या पाठ का उपयोग करें.",
    "Запись оказалась пустой. Попробуйте ещё раз.": "रिकॉर्ड खाली है, फिर से प्रयास करें।",
