    "Запишите понятное объяснение или вопрос. Не оставляйте непонятные пункты без внимания.": "एक स्पष्ट स्पष्टीकरण या प्रश्न लिखें। अस्पष्ट बिंदुओं को ध्यान से न छोड़ें।",
    "Запишите рассказ и добавьте короткое пояснение для специалиста.": "एक कहानी लिखें और विशेषज्ञ के लिए एक संक्षिप्त विवरण जोड़ें।",
