    "Здесь появятся ваши записи о звонках, встречах и следующих шагах.": "आपके कॉल, मीटिंग और अगले कदमों के रिकॉर्ड यहां दिखाई देंगे।",
    "Здесь — внешние официальные сервисы и организации, не подключённые партнёры «Моста». Язык приёма, стоимость, часы и возможность записи нужно уточнить у них. Ссылки сверены 15.11.2026.": "यहां बाहरी आधिकारिक सेवाएं और संगठन हैं, जो ब्रिज के कनेक्टेड पार्टनर नहीं हैं। प्राप्त करने की भाषा, लागत, घंटे और रिकॉर्डिंग की क्षमता को उनके पास स्पष्ट करना आवश्यक है। लिंक की तुलना 15.11.2026 से की गई है।",
