    "Из какой страны": "किस देश से",
    "Изменение и прекращение договора": "अनुबंध में संशोधन और समाप्ति",
    "Изменение условий": "शर्तों में बदलाव",
    "Изменения остаются в памяти этой вкладки до успешного сохранения. Проверяйте статус вверху и скачайте копию перед закрытием, если сохранение приостановлено.": "परिवर्तन सफल सहेजने तक इस टैब में रहते हैं. यदि सहेजने पर रोक है तो ऊपर से स्थिति की जांच करें और बंद करने से पहले प्रति डाउनलोड करें.",
    "Изменения подготовлены. Статус сохранения — вверху экрана.": "परिवर्तन तैयार हैं। स्क्रीन के शीर्ष पर सहेजें।",
