    "Имя или организация": "नाम या संगठन",
    "Инструмент ищет несколько известных формулировок риска. Он не проверяет человека по базам и не даёт оценку «безопасно». Сомнения можно обсудить со специалистом.": "यह उपकरण जोखिम के कुछ ज्ञात रूपों की तलाश करता है। यह किसी व्यक्ति के आधार पर जांच नहीं करता है और यह सुरक्षित रूप से मूल्यांकन नहीं करता है। संदेह विशेषज्ञों के साथ चर्चा किया जा सकता है।",
    "Информационный портал": "सूचना पोर्टल",
    "Информационный ресурс с материалами для мигрантов и работающих с ними специалистов.": "प्रवासी और उनके साथ काम करने वाले विशेषज्ञों के लिए सामग्री के साथ एक सूचना संसाधन।",
    "История моих заметок и действий": "मेरे नोट्स और कार्यों का इतिहास",
    "Источник:": "स्रोत:",
    "Кабыл алууда котормочу керекпи?": "क्या आप एक कटोरा के लिए एक कटोरा के लिए एक कटोरा के लिए एक कटोरा है?",
