    "Как записаться на встречу с учителем?": "एक शिक्षक से मिलने के लिए कैसे बुक करें?",
    "Как к вам обращаться?": "आप कैसे हैं?",
    "Как ко мне обращаться": "कैसे मुझसे बात करें",
