    "Как учитываются часы, перерывы и дополнительные смены?": "घंटों, ब्रेक और अतिरिक्त कार्य के लिए क्या है?",
    "Как я могу связаться с классным руководителем?": "मैं कक्षा प्रमुख से कैसे संपर्क करूं?",
    "Какая помощь нужна": "क्या मदद चाहिए",
    "Какие документы нужно принести?": "आपको कौन से दस्तावेज लाने चाहिए?",
    "Какие расходы беру на себя": "मैं अपने ऊपर क्या खर्च करता हूँ",
    "Какие суммы могут удержать, по какой причине и где это прописано?": "वे किस राशि को रोक सकते हैं, किस कारण से और कहां?",
    "Какие условия закреплены письменно и как подтвердить оплату и обязанности сторон?": "लिखित में कौन-सी शर्तें हैं और पक्षों के भुगतान और दायित्वों की पुष्टि कैसे की जाती है?",
    "Какие условия могут измениться и как об этом сообщат?": "क्या परिस्थितियां बदल सकती हैं और कैसे इसकी सूचना दी जाती है?",
    "Какой у меня график работы?": "मेरे काम का समय क्या है?",
    "Кандай документтерди алып келиш керек?": "आपको कौन से दस्तावेज ले जाने चाहिए?",
    "Карточки для печати": "छापने योग्य कार्ड",
    "Класс жетекчиси менен кантип байланышсам болот?": "कक्षा में नेतृत्व कैसे कर सकते हैं?",
    "Когда будет выплата зарплаты?": "वेतन कब मिलेगा?",
    "Когда и как возвращается залог?": "कब और कैसे जमा किया जाता है?",
    "Когда можно связаться, на каком языке": "कब संपर्क करना है, किस भाषा में",
    "Когда помощь особенно нужна": "जब मदद की ज़रूरत होती है",
