    "Не загружайте настоящие паспортные, медицинские и другие чувствительные сведения в публичный пилот. Любой пользователь этого профиля браузера может открыть записи. Очищать и скачивать копию можно в профиле.": "सार्वजनिक पायलट में असली पासपोर्ट, चिकित्सा या अन्य संवेदनशील जानकारी डाउनलोड न करें. इस ब्राउज़र प्रोफ़ाइल का कोई भी उपयोगकर्ता रिकॉर्ड खोल सकता है. आप अपनी प्रोफ़ाइल में क्लीन और डाउनलोड कर सकते हैं।",
    "Не передавайте пароли и коды из сообщений. Уточните запрос через официальный канал организации.": "संदेशों के पासवर्ड और कोड न दें। संगठन के आधिकारिक चैनल के माध्यम से पूछताछ को स्पष्ट करें।",
    "Не принимайте решение только по результату автоматического поиска.": "केवल स्वचालित खोज के परिणामों के आधार पर निर्णय न लें।",
    "Не удалось выполнить действие.": "कार्रवाई नहीं की जा सकी।",
    "Не удалось загрузить настройки подключения. Подключитесь к интернету и обновите страницу.": "कनेक्टिविटी सेटिंग्स डाउनलोड नहीं हो पाई. इंटरनेट से कनेक्ट हो जाओ और पेज को अपडेट करें.",
    "Не удалось загрузить настройки сервера. Обновите страницу с интернетом.": "सर्वर सेटिंग्स डाउनलोड नहीं हो पाई. वेब पेज को अपडेट करें.",
    "Не удалось записать аудио. Используйте текст или прикрепите файл.": "ऑडियो रिकॉर्ड नहीं किया जा सका. पाठ का उपयोग करें या फ़ाइल संलग्न करें.",
    "Не удалось озвучить фразу. Проверьте доступность русского голоса на устройстве.": "एक वाक्यांश नहीं सुना जा सका। डिवाइस पर रूसी आवाज की उपलब्धता की जांच करें।",
    "Не удалось определить режим личного кабинета.": "निजी कैबिनेट का मोड नहीं मिला।",
