    "Скачается текстовый файл. Вложения в него не включаются, их можно скачать отдельно.": "एक पाठ फ़ाइल डाउनलोड की जाती है. इसमें सम्मिलित नहीं होते हैं, आप उन्हें अलग से डाउनलोड कर सकते हैं.",
